/* Lot 116: cap, ic and the root's rex, rch, rcap and ric against the engine's font (generated by scripts/lot116_gen.py; expectations from scripts/lot116_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[2048];
static char g_a[4096], g_b[4096], g_c[4096], g_r[16384];

/* the style attributes and the node lines of the report */
static void facts(const char *css, char *out, int cap) {
    int i, n = 0;
    char *p, *e;
    snprintf(g_html, sizeof(g_html), "<html><head><style>@keyframes k { from { color: #000000 } to { color: "
             "#ffffff } } %s</style></head><body><div id=b><div id=o><p id=i>i</p><p>a</p><p>b</p></div></div>"
             "</body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    out[0] = 0;
    for (i = 0; i < g_d.nnodes; i++) {
        char s[512];
        s[0] = 0;
        wf_site_style_attr(&g_d, g_d.node[i].start, s, (int)sizeof(s));
        n += snprintf(out + n, (size_t)(cap - n), "%d:%s|", i, s);
    }
    TEST_ASSERT_TRUE(wf_site_report(&g_d, g_r, (int)sizeof(g_r)) > 0);
    for (p = g_r; (p = strstr(p, "node ")) != 0 && n < cap - 1; p = e) {
        e = strchr(p, '\n');
        if (!e) e = p + strlen(p);
        n += snprintf(out + n, (size_t)(cap - n), "%.*s|", (int)(e - p), p);
    }
}

/* the sheet with the unit and the sheet with the model's px agree;
 * the sheet without the declaration differs (the unit is read) */
static void same3(const char *with_unit, const char *as_px, const char *without) {
    facts(with_unit, g_a, (int)sizeof(g_a));
    facts(as_px, g_b, (int)sizeof(g_b));
    facts(without, g_c, (int)sizeof(g_c));
    TEST_ASSERT_EQUAL_STRING(g_b, g_a);
    TEST_ASSERT_TRUE(strcmp(g_a, g_c) != 0);
}

