    same3("html { font-size: 30px } #b { font-size: 64px } #o { font-size: 40px; overflow: auto; height: 1cap } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", "html { font-size: 30px } #b { font-size: 64px } #o { font-size: 40px; overflow: auto; height: 18px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", "html { font-size: 30px } #b { font-size: 64px } #o { font-size: 40px; overflow: auto; } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
