    same3("html { font-size: 30px } #b { font-size: 64px } #o { font-size: 30px; overflow: auto; height: calc(1.5ch + 10%) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", "html { font-size: 30px } #b { font-size: 64px } #o { font-size: 30px; overflow: auto; height: calc(24px + 10%) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", "html { font-size: 30px } #b { font-size: 64px } #o { font-size: 30px; overflow: auto } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
